204		ch := l.next() // read character after '/'
205		switch ch {
206		case 'a', 'b', 'f', 'n', 'r', 't', 'v', '\\', quote:
207			// nothing to do
208			ch = l.next()
209		case '0', '1', '2', '3', '4', '5', '6', '7':
