215			if l.peek() == '{' {
216				// consume '{'
217				l.next()
218				// read 1-6 hex digits
219				digits := 0
220				for {
221					p := l.peek()
222					if p == '}' {
223						break
224					}
225					if digitVal(p) >= 16 {
226						l.error("invalid char escape")
227						return eof
228					}
229					if digits >= 6 {
230						l.error("invalid char escape")
231						return eof
232					}
233					l.next()
234					digits++
235				}
236				if l.peek() != '}' || digits == 0 {
237					l.error("invalid char escape")
238					return eof
239				}
240				// consume '}' and continue
241				l.next()
242				ch = l.next()
243				break
244			}
245			ch = l.scanDigits(l.next(), 16, 4)
246		case 'U':
247			ch = l.scanDigits(l.next(), 16, 8)
248		default:
249			l.error("invalid char escape")
250		}
251		return ch
252	}
